/**
 * Types for `@gate/console/server`: dist-server/domain.mjs, built from src/server/entry.ts by
 * scripts/build-server.mjs. Hand-written, because the console's sources compile under their own settings (paths,
 * TypeScript version) and cannot be part of another package's program. Only what the server uses is typed; the
 * operation namespaces are reached through `opsManifest` paths. src/server/declared.ts checks this file against
 * the real exports whenever the console is typechecked.
 */

/** One operation the RPC door may run (generated by scripts/op-manifest.mjs). */
export interface OpEntry {
  /** What the client calls it: `api.decide`, `work.reauth`, `orgApi.changeRole` … */
  name: string;
  /** Export path from the bundle's root to the function; the last step is the function, the one before is `this`. */
  path: string[];
  params: string[];
  /** Indexes of optional (or defaulted) parameters. */
  optional: number[];
  /** Index of the organisation-id parameter, or null when the operation takes none. */
  org: number | null;
  /** Indexes of the parameters that name the person acting. */
  actors: number[];
  /** Actor-named properties of object parameters written as literals in the signature (e.g. input.decidedBy). */
  actorProps: { index: number; props: string[] }[];
  rest: boolean;
  async: boolean;
}

export interface OpsManifest {
  generatedFrom: string;
  orgParams: string[];
  actorParams: string[];
  ops: OpEntry[];
}

/** An organisation document as saved (the console's OrgDB without its signing keys). */
export interface SavedDoc {
  org: { id: string; name: string };
  members: { userId: string; role: string; status: string }[];
}

export interface Persistence {
  load(orgId: string): SavedDoc | undefined;
  save(orgId: string, doc: SavedDoc): void;
}

/** A receipt as the console's documents hold it (apps/console/src/types.ts Receipt; the server's come from the real chain). */
export interface DocReceipt {
  seq: number;
  ts: string;
  org: string;
  kind: string;
  agent?: string;
  tool?: string;
  action?: string;
  actor?: string;
  decision?: string;
  ref_seq?: number;
  details?: Record<string, unknown>;
  prev_hash: string;
  kid: string;
  hash: string;
  sig: string;
}

/** A checkpoint as the console's documents hold it. */
export interface DocCheckpoint {
  id: string;
  org: string;
  seq: number;
  hash: string;
  ts: string;
  kid: string;
  sig: string;
  onDemand?: boolean;
}

/** Where the domain's receipts go on the server: the organisation's real chain (src/mock/db.ts ChainWriter). */
export interface ChainWriter {
  base(orgId: string): { seq: number; hash: string };
  history(orgId: string, generated: DocReceipt[]): DocReceipt[];
  receipt(orgId: string, r: DocReceipt): void;
  checkpoint(orgId: string, cp: DocCheckpoint): void;
}

export interface DomainDb {
  setChainWriter(w: ChainWriter | undefined, nonce?: string): void;
  /** What a provisional receipt's hash (and signature) start with until the real chain's replace them. */
  readonly PENDING: string;
  /** The refusal of anything that would sign with the organisation's key in the domain (the server holds none). */
  readonly NO_KEY: string;
  /** Record an admin action (a receipt) in an open organisation. */
  logAdmin(orgId: string, userId: string, action: string, details: Record<string, string | number | boolean>, agent?: string): DocReceipt;
  setPersistence(p: Persistence | undefined): void;
  exportDoc(orgId: string): SavedDoc | undefined;
  importDoc(orgId: string, doc: SavedDoc): void;
  dropFromMemory(orgId: string): void;
  getDB(orgId: string): SavedDoc;
  peekDB(orgId: string): SavedDoc | undefined;
  setActiveOrg(orgId: string | undefined): void;
  syncOrgMeta(org: SavedDoc["org"]): void;
  orgIds(): string[];
  subscribe(fn: (orgId: string, kind: string) => void): () => void;
}

export declare const opsManifest: OpsManifest;
export declare const db: DomainDb;
/** Wait until every timer the domain set has fired (and whatever those set). False if it gave up. */
export declare function settle(maxRounds?: number): Promise<boolean>;
/** Cancel every domain timer that has not fired yet. */
export declare function cancelPending(): void;
/** Hold every domain timer (they run once the returned function is called). */
export declare function holdTimers(): () => void;
export declare const api: object;
export declare const orgApi: object;
export declare const work: object;
export declare const agents: object;
export declare const assessments: object;
export declare const sovereign: object;
export declare const deployment: object;

/** The console's in-browser chain verifier (src/lib/crypto.ts verifyChain), as the browser runs it. */
export interface VerifyReport {
  result: "verified" | "failed" | "cannot_verify";
  receipts: number;
  brokenAt?: number;
  brokenReason?: string;
  checkpoints: { total: number; valid: number };
  keyFingerprint?: string;
}
export declare const chainVerifier: {
  verifyChain(receipts: DocReceipt[], keys: Record<string, string>, checkpoints?: DocCheckpoint[], opts?: { expectedPrev?: string }): VerifyReport;
};

/** What the organisation's key signs, each asked of Elan1 Govern as a structured request (src/lib/crypto.ts). */
export type SigningKind = "disclosure" | "disclosure-bundle" | "sd-jwt" | "evidence-manifest" | "pack-manifest" | "usage-statement" | "residency" | "erasure";
export interface OrgSigner {
  kid(orgId: string): string;
  request(orgId: string, kind: SigningKind, input: unknown): string;
}
/** A Seal v6 record (src/types.ts SealRecord). */
export interface DocSeal {
  format: "elan1.seal.v6";
  seq: number;
  receiptHash: string;
  level: string;
  fields: { id: string; name: string; value: string }[];
  preimageBytes: number;
  digest: string;
  kid: string;
  sig: string;
  payloadUnbound?: boolean;
}
/** A timestamped Merkle batch as the console lists it (src/types.ts AnchorBatch), with real RFC 3161 tokens. */
export interface DocAnchorBatch {
  id: string;
  windowStart: string;
  windowEnd: string;
  firstSeq: number;
  lastSeq: number;
  count: number;
  root: string;
  tokens: { tsaId: string; tsaName: string; genTime: string; serial: string; policyOid: string; status: "granted" | "granted_late"; imprint: string; sig: string; delaySeconds: number; der?: string; chain?: string[] }[];
  status: "anchored" | "late";
}
export interface DocTsaAuthority {
  id: string;
  name: string;
  scope: "India" | "Global" | "Local";
  url: string;
  policyOid: string;
  publicKey: string;
  fingerprint: string;
  status: "operational" | "degraded";
  certPem?: string;
}
export interface ServerEvidence {
  seal(orgId: string, seq: number, receiptHash: string): DocSeal | undefined;
  batches(orgId: string): DocAnchorBatch[];
  authorities(orgId: string): DocTsaAuthority[];
}
export declare const serverSigning: {
  setOrgSigner(s: OrgSigner | undefined): void;
  setServerEvidence(e: ServerEvidence | undefined): void;
  sealPlan(db: SavedDoc, fromSeq: number): { fromSeq?: number; autonomy: Record<string, string>; levels: { level: string; fromSeq: number }[] };
  noteErased(db: SavedDoc, seq: number, payloadHash: string, recordId: string): void;
  /** Successor keys (src/mock/keys.ts): the step Elan1 Govern took, handed to the console's bookkeeping, and its checks. */
  serverKeys: {
    setStep(s: { kid: string; publicKeyHex: string; seq: number; switchAt?: string } | undefined): void;
    bindCheck(orgId: string, userId: string, input: { purpose: "planned" | "compromise"; holders?: string[] }): void;
    ceremonyCheck(orgId: string, userId: string, participantNames?: string[], via?: "ceremony" | "kms"): void;
    boundOf(orgId: string): { kid: string; boundBy: string; purpose: string; switchAt?: string } | undefined;
  };
};

/** The console's in-browser Seal v6 verifier (src/lib/verify6.ts), as the browser runs it. */
export interface BundleVerifyResult {
  code: string;
  exitCode: number;
  variants: string[];
  headline: string;
  sections: { id: string; state: string; detail: string }[];
}
export declare const bundleVerifier: {
  verifyBundle(input: unknown, opts?: { expectedFingerprint?: string; profileId?: string; now?: number }): BundleVerifyResult;
};
